changeSet.sql:
SET LOCAL lock_timeout = '5s';
DO $q$
BEGIN
    IF to_regclass('nexus.aspect_extraction_queue') IS NOT NULL
       AND EXISTS (SELECT 1 FROM pg_attribute a
                    WHERE a.attrelid = to_regclass('nexus.aspect_extraction_queue') AND a.attname = 'collection_id' AND NOT a.attisdropped) THEN
        IF NOT EXISTS (SELECT 1 FROM pg_constraint
                        WHERE conrelid = to_regclass('nexus.aspect_extraction_queue') AND conname = 'aspect_extraction_queue_collection_id_fk') THEN
            ALTER TABLE nexus.aspect_extraction_queue ADD CONSTRAINT aspect_extraction_queue_collection_id_fk FOREIGN KEY (tenant_id, collection_id) REFERENCES nexus.catalog_collections (tenant_id, collection_id) ON DELETE CASCADE NOT VALID;
        END IF;
    END IF;
END
$q$;

rollback.sql:
DO $q$
BEGIN
    IF to_regclass('nexus.aspect_extraction_queue') IS NOT NULL THEN
        ALTER TABLE nexus.aspect_extraction_queue DROP CONSTRAINT IF EXISTS aspect_extraction_queue_collection_id_fk;
    END IF;
END
$q$;
